from pathlib import Path
root=Path('outputs')
s=(root/'tomeris_plan_history_ui_v0131.py').read_text(encoding='utf-8-sig')
s=s.replace('from tomeris_plan_history import describe','from tomeris_plan_reflection import describe\nfrom tomeris_reflection_ui import ReflectionPanel')
s=s.replace("        self.carry_button.pack(side='left')", "        self.carry_button.grid(row=1,column=0,sticky='w',pady=(6,0))\n        footer.columnconfigure(0,weight=1)\n        self.reflect_button=ttk.Button(footer,text='この計画の振り返りを書く',command=self.reflect)\n        self.reflect_button.grid(row=0,column=0,sticky='w')")
s=s.replace("self.exit_button.pack(side='right')","self.exit_button.grid(row=1,column=1,sticky='e',pady=(6,0))")
s=s.replace('self.list,self.carry_button]', 'self.list,self.carry_button,self.reflect_button]')
s=s.replace('    def carry(self):', "    def reflect(self):\n        if self.app.busy or self.app.closing: return\n        selected=self.list.curselection()\n        if not selected or selected[0]>=len(self.visible):\n            self.message.set('振り返る計画を一覧から選んでください。'); return\n        self.app.reflection_panel=ReflectionPanel(self,self.visible[selected[0]]['id'])\n    def carry(self):")
(root/'tomeris_plan_history_ui_v014.py').write_text(s,encoding='utf-8')
s=(root/'tomeris_desktop_v0131.py').read_text(encoding='utf-8-sig').replace('v0.13.1','v0.14')
s=s.replace('from tomeris_plan_carry import DesktopService as PlanService','from tomeris_plan_reflection import DesktopService as PlanService')
s=s.replace('from tomeris_plan_history_ui_v0131 import','from tomeris_plan_history_ui_v014 import')
s=s.replace('    def open_google(self):',"        panel=getattr(self,'reflection_panel',None)\n        if panel is not None:\n            panel.state()\n    def open_google(self):")
(root/'tomeris_desktop_v014.py').write_text(s,encoding='utf-8')
